from pathlib import Path

INDEX = Path('archive-demo/index.html')
SW = Path('archive-demo/sw.js')
text = INDEX.read_text(encoding='utf-8')


def replace_line(prefix: str, new_text: str):
    global text
    lines = text.splitlines()
    hits = [i for i, line in enumerate(lines) if line.startswith(prefix)]
    if len(hits) != 1:
        raise RuntimeError(f'Expected one line starting with {prefix!r}, found {len(hits)}')
    lines[hits[0]] = new_text
    text = '\n'.join(lines)


def insert_after(prefix: str, block: str):
    global text
    lines = text.splitlines()
    hits = [i for i, line in enumerate(lines) if line.startswith(prefix)]
    if len(hits) != 1:
        raise RuntimeError(f'Expected one insertion point {prefix!r}, found {len(hits)}')
    lines[hits[0] + 1:hits[0] + 1] = block.splitlines()
    text = '\n'.join(lines)


